/// <summary>
/// Scoped service that holds the current low-stock alert count and notifies all
/// subscribed components when new data arrives. Because it is scoped, each user
/// circuit gets its own independent instance.
/// </summary>
public class AlertState
{
    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public void UpdateCount(int newCount)
    {
        LowStockCount = newCount;
        OnChange?.Invoke();
    }
}

